const common={'Cache-Control':'no-store','X-Robots-Tag':'noindex, nofollow','X-Content-Type-Options':'nosniff','Referrer-Policy':'same-origin'};
const routes={'/':'original','/atelier':'atelier','/radar':'radar'};
const allowedNext=new Set(Object.keys(routes));
const imgSrc="img-src data: https://cache.marriott.com https://www.thavornpalmbeach.com https://www.chanalai.com";
const pageCsp={
  original:`default-src 'none'; script-src 'unsafe-inline'; style-src 'unsafe-inline'; ${imgSrc}; base-uri 'none'; frame-ancestors 'none'; form-action 'none'`,
  atelier:`default-src 'none'; script-src 'unsafe-inline'; style-src 'unsafe-inline' https://fonts.googleapis.com; font-src https://fonts.gstatic.com; ${imgSrc}; base-uri 'none'; frame-ancestors 'none'; form-action 'none'`,
  radar:`default-src 'none'; script-src 'unsafe-inline'; style-src 'unsafe-inline' https://fonts.googleapis.com; font-src https://fonts.gstatic.com; ${imgSrc}; base-uri 'none'; frame-ancestors 'none'; form-action 'none'`
};
const loginCsp={
  original:"default-src 'none'; script-src 'unsafe-inline'; style-src 'unsafe-inline'; form-action 'self'; base-uri 'none'; frame-ancestors 'none'",
  atelier:"default-src 'none'; script-src 'unsafe-inline'; style-src 'unsafe-inline' https://fonts.googleapis.com; font-src https://fonts.gstatic.com; form-action 'self'; base-uri 'none'; frame-ancestors 'none'",
  radar:"default-src 'none'; script-src 'unsafe-inline'; style-src 'unsafe-inline' https://fonts.googleapis.com; font-src https://fonts.gstatic.com; form-action 'self'; base-uri 'none'; frame-ancestors 'none'"
};
const loginKey={original:'loginOriginal',atelier:'loginAtelier',radar:'loginRadar'};
async function matches(a,b){const e=new TextEncoder();const [x,y]=await Promise.all([crypto.subtle.digest('SHA-256',e.encode(a)),crypto.subtle.digest('SHA-256',e.encode(b))]);const xx=new Uint8Array(x),yy=new Uint8Array(y);let d=0;for(let i=0;i<xx.length;i++)d|=xx[i]^yy[i];return d===0}
async function sign(value,secret){const e=new TextEncoder();const key=await crypto.subtle.importKey('raw',e.encode(secret),{name:'HMAC',hash:'SHA-256'},false,['sign']);return Array.from(new Uint8Array(await crypto.subtle.sign('HMAC',key,e.encode(value))),b=>b.toString(16).padStart(2,'0')).join('')}
function login(theme='original',error=false){
  const err=error?'<p class="error" role="alert">The username or password is incorrect. Please try again.</p>':'';
  const html=(pages[loginKey[theme]]||'').replace('<!--LOGIN_ERROR-->',err);
  return new Response(html,{status:error?401:200,headers:{...common,'Content-Type':'text/html; charset=utf-8','Content-Security-Policy':loginCsp[theme]}});
}
export default {async fetch(request,env){
 if(!env.PITCH_USERNAME||!env.PITCH_PASSWORD)return new Response('Access is not configured.',{status:503,headers:common});
 const url=new URL(request.url);const secret=env.PITCH_PASSWORD+':'+env.PITCH_USERNAME;
 if(url.pathname==='/login'&&request.method==='POST'){
  if(request.headers.get('Origin')!==url.origin)return new Response('Invalid request origin.',{status:403,headers:common});
  const body=await request.text();if(body.length>2048)return new Response('Request too large.',{status:413,headers:common});
  const form=new URLSearchParams(body);
  const next=allowedNext.has(form.get('next')||'')?(form.get('next')||'/'):'/';
  const loginTheme=routes[next]||'original';
  if(!await matches((form.get('username')||'')+':'+(form.get('password')||''),env.PITCH_USERNAME+':'+env.PITCH_PASSWORD))return login(loginTheme,true);
  const expiry=String(Date.now()+8*60*60*1000),token=expiry+'.'+await sign(expiry,secret);
  return new Response(null,{status:303,headers:{...common,Location:next, 'Set-Cookie':'hph_session='+token+'; HttpOnly; Secure; SameSite=Lax; Path=/; Max-Age=28800'}});
 }
 if(!['GET','HEAD'].includes(request.method))return new Response('Method not allowed',{status:405,headers:common});
 const cookies=request.headers.get('Cookie')||'';const token=cookies.split(';').map(c=>c.trim()).find(c=>c.startsWith('hph_session='))?.slice(12)||'';
 const [expiry,sig]=token.split('.');let authorized=false;
 if(/^\d{13}$/.test(expiry||'')&&/^[a-f0-9]{64}$/.test(sig||'')&&Number(expiry)>Date.now()&&Number(expiry)<=Date.now()+28800000)authorized=await matches(sig,await sign(expiry,secret));
 const theme=routes[url.pathname];
 if(!authorized)return login(theme||'original');
 if(!theme)return new Response('Not found',{status:404,headers:common});
 return new Response(request.method==='HEAD'?null:pages[theme],{headers:{...common,'Content-Type':'text/html; charset=utf-8','Content-Security-Policy':pageCsp[theme]}});
}};
